function hexToRgb(hex) {
  const clean = hex.replace('#', '');
  const num = parseInt(clean, 16);
  return { r: ((num >> 16) & 255) / 255, g: ((num >> 8) & 255) / 255, b: (num & 255) / 255 };
}

function parseColor(value) {
  if (value.startsWith('#')) return hexToRgb(value);
  const rgba = value.match(/^rgba?\(([^)]+)\)$/);
  if (!rgba) return null;
  const parts = rgba[1].split(',').map((part) => part.trim());
  const [r, g, b] = parts.slice(0, 3).map((part) => Number(part) / 255);
  const a = parts[3] === undefined ? 1 : Number(parts[3]);
  return { r, g, b, a };
}

function paint(hex) {
  const color = parseColor(hex);
  return [{ type: 'SOLID', color: { r: color.r, g: color.g, b: color.b }, opacity: color.a ?? 1 }];
}

function parsePx(value) {
  if (typeof value === 'number') return value;
  const match = String(value).match(/^-?\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : null;
}

function parseMs(value) {
  const text = String(value).trim();
  if (text.endsWith('ms')) return Number(text.slice(0, -2));
  if (text.endsWith('s')) return Number(text.slice(0, -1)) * 1000;
  return parsePx(text);
}

function ensureCollection(name, modeNames) {
  let collection = figma.variables.getLocalVariableCollections().find((item) => item.name === name);
  if (!collection) collection = figma.variables.createVariableCollection(name);
  const firstMode = collection.modes[0];
  if (firstMode && firstMode.name !== modeNames[0]) collection.renameMode(firstMode.modeId, modeNames[0]);
  for (const modeName of modeNames.slice(1)) {
    if (!collection.modes.some((mode) => mode.name === modeName)) collection.addMode(modeName);
  }
  return collection;
}

function modeId(collection, name) {
  return collection.modes.find((mode) => mode.name === name).modeId;
}

function variableScopes(type, name) {
  if (type === 'COLOR') {
    if (name.startsWith('label/')) return ['TEXT_FILL'];
    if (name.startsWith('line/')) return ['STROKE_COLOR'];
    if (name.includes('focus-ring')) return ['STROKE_COLOR', 'EFFECT_COLOR'];
    if (
      name.startsWith('accent/') ||
      name.startsWith('ai/') ||
      name.startsWith('file/') ||
      name.startsWith('state/') ||
      name.includes('/bg') ||
      name.includes('/hover') ||
      name.includes('/pressed')
    ) {
      return ['FRAME_FILL', 'SHAPE_FILL', 'TEXT_FILL', 'STROKE_COLOR'];
    }
    return ['FRAME_FILL', 'SHAPE_FILL'];
  }
  if (name.startsWith('radius/')) return ['CORNER_RADIUS'];
  if (name.startsWith('spacing/')) return ['GAP', 'WIDTH_HEIGHT'];
  return [];
}

function localVariable(collection, type, name) {
  let variable = figma.variables
    .getLocalVariables(type)
    .find((item) => item.variableCollectionId === collection.id && item.name === name);
  if (!variable) variable = figma.variables.createVariable(name, collection, type);
  variable.scopes = variableScopes(type, name);
  if (variable.setVariableCodeSyntax) {
    const cssName = '--polaris-' + name.replaceAll('/', '-');
    try {
      variable.setVariableCodeSyntax('WEB', type === 'COLOR' ? 'var(' + cssName + ')' : cssName);
    } catch {}
  }
  return variable;
}

function tokenName(cssVarName) {
  return cssVarName.replace('--polaris-', '').replaceAll('-', '/');
}

function setColorVariables() {
  const collection = ensureCollection('Polaris / Color', ['Light', 'Dark']);
  const lightMode = modeId(collection, 'Light');
  const darkMode = modeId(collection, 'Dark');
  const light = POLARIS_SYNC_DATA.tokens.cssVariables.light;
  const dark = POLARIS_SYNC_DATA.tokens.cssVariables.dark;
  for (const [cssName, lightValue] of Object.entries(light)) {
    const parsed = parseColor(lightValue);
    if (!parsed) continue;
    const variable = localVariable(collection, 'COLOR', tokenName(cssName));
    variable.setValueForMode(lightMode, parsed);
    variable.setValueForMode(darkMode, parseColor(dark[cssName] || lightValue) || parsed);
  }
}

function setNumberVariables() {
  const collection = ensureCollection('Polaris / Number', ['Base']);
  const baseMode = modeId(collection, 'Base');
  const categories = POLARIS_SYNC_DATA.tokens.cssVariables.categorizedLight;
  const numberGroups = {
    radius: categories.radius,
    spacing: categories.spacing,
    zIndex: categories.zIndex,
  };
  for (const [group, values] of Object.entries(numberGroups)) {
    for (const [name, value] of Object.entries(values)) {
      const numberValue = parsePx(value);
      if (numberValue === null) continue;
      const variable = localVariable(collection, 'FLOAT', group + '/' + name);
      variable.setValueForMode(baseMode, numberValue);
    }
  }
  for (const [name, value] of Object.entries(categories.motion)) {
    if (!name.startsWith('duration-')) continue;
    const variable = localVariable(collection, 'FLOAT', 'motion/' + name.replace('duration-', 'duration/'));
    variable.setValueForMode(baseMode, parseMs(value));
  }
}

async function loadFont(fontName) {
  try {
    await figma.loadFontAsync(fontName);
    return fontName;
  } catch {
    const fallback = { family: 'Inter', style: fontName.style === 'Bold' ? 'Bold' : 'Regular' };
    await figma.loadFontAsync(fallback);
    return fallback;
  }
}

async function setTextStyles() {
  const typography = POLARIS_SYNC_DATA.tokens.designFrontmatter.typography || {};
  for (const [name, spec] of Object.entries(typography)) {
    const weight = Number(spec.fontWeight) >= 700 ? 'Bold' : 'Regular';
    const fontName = await loadFont({ family: 'Pretendard', style: weight });
    let style = figma.getLocalTextStyles().find((item) => item.name === 'Polaris/' + name);
    if (!style) style = figma.createTextStyle();
    style.name = 'Polaris/' + name;
    style.fontName = fontName;
    style.fontSize = parsePx(spec.fontSize);
    style.lineHeight = { unit: 'PIXELS', value: Math.round(parsePx(spec.fontSize) * Number(spec.lineHeight)) };
    style.letterSpacing = { unit: 'PIXELS', value: 0 };
    style.description = 'Synced from PolarisDesign ' + POLARIS_SYNC_DATA.tokens.source.commit;
  }
}

function parseShadowLayer(layer) {
  const match = layer
    .trim()
    .match(/^(-?\d+)(?:px)?\s+(-?\d+)px\s+(\d+)px\s+(rgba?\([^)]+\))/);
  if (!match) return null;
  const color = parseColor(match[4]);
  if (!color) return null;
  return {
    type: 'DROP_SHADOW',
    visible: true,
    blendMode: 'NORMAL',
    color: { r: color.r, g: color.g, b: color.b, a: color.a ?? 1 },
    offset: { x: Number(match[1]), y: Number(match[2]) },
    radius: Number(match[3]),
    spread: 0,
  };
}

function splitShadow(value) {
  return String(value).split(/,\s*(?=-?\d+(?:px)?\s)/).map((part) => part.trim());
}

function setEffectStyles() {
  const shadows = POLARIS_SYNC_DATA.tokens.cssVariables.categorizedLight.shadow || {};
  for (const [name, value] of Object.entries(shadows)) {
    if (String(value).includes('color-mix')) continue;
    const effects = splitShadow(value).map(parseShadowLayer).filter(Boolean);
    if (effects.length === 0) continue;
    let style = figma.getLocalEffectStyles().find((item) => item.name === 'Polaris/shadow/' + name);
    if (!style) style = figma.createEffectStyle();
    style.name = 'Polaris/shadow/' + name;
    style.effects = effects;
    style.description = 'Synced from PolarisDesign shadow token.';
  }
}

async function makeText(text, size, weight, color, width) {
  const fontName = await loadFont({ family: 'Pretendard', style: weight });
  const node = figma.createText();
  node.characters = text;
  node.fontName = fontName;
  node.fontSize = size;
  node.lineHeight = { unit: 'PIXELS', value: Math.round(size * 1.45) };
  node.fills = paint(color);
  if (width) {
    node.resize(width, node.height);
    node.textAutoResize = 'HEIGHT';
  }
  return node;
}

function auto(frame, dir, gap, pad) {
  frame.layoutMode = dir;
  frame.itemSpacing = gap;
  frame.paddingTop = frame.paddingRight = frame.paddingBottom = frame.paddingLeft = pad;
  frame.primaryAxisSizingMode = 'AUTO';
  frame.counterAxisSizingMode = 'AUTO';
}

async function ensurePage(name) {
  let page = figma.root.children.find((item) => item.name === name);
  if (!page) page = figma.createPage();
  if (page.loadAsync) await page.loadAsync();
  page.name = name;
  page.children.forEach((child) => child.remove());
  return page;
}

async function buildContractPage() {
  const page = await ensurePage('00 Polaris Output Contract');
  const root = figma.createFrame();
  root.name = 'Polaris Output Contract';
  root.resize(1440, 1200);
  root.fills = paint('#F7F8F9');
  auto(root, 'VERTICAL', 28, 64);
  page.appendChild(root);
  root.appendChild(await makeText('Polaris Output Contract', 40, 'Bold', '#26282B', 980));
  root.appendChild(
    await makeText(
      'Synced from PolarisDesign ' + POLARIS_SYNC_DATA.tokens.source.commit + '. Read DESIGN.md, print Polaris UI Brief, then create Figma/Web output.',
      16,
      'Regular',
      '#454C53',
      980
    )
  );
  root.appendChild(
    await makeText(
      'Required brief fields: purpose, user/context, tone, signature asset, component mapping, token/color rules, banned choices, verification.',
      14,
      'Regular',
      '#454C53',
      980
    )
  );
}

async function buildTokenPage() {
  const page = await ensurePage('Polaris DS - Tokens');
  const root = figma.createFrame();
  root.name = 'Polaris Token Specimen';
  root.resize(1440, 2600);
  root.fills = paint('#FFFFFF');
  auto(root, 'VERTICAL', 32, 64);
  page.appendChild(root);
  root.appendChild(await makeText('Polaris Tokens', 32, 'Bold', '#26282B', 1000));
  root.appendChild(
    await makeText(
      'CSS variables: ' + POLARIS_SYNC_DATA.tokens.counts.cssVariableLines + ' lines. Text styles: ' + POLARIS_SYNC_DATA.tokens.counts.textStyles + '.',
      14,
      'Regular',
      '#454C53',
      1000
    )
  );

  root.appendChild(
    await makeText(
      'GitHub Pages token sections: ' + POLARIS_SYNC_DATA.tokenRegistry.pagesReference.sections.join(' / '),
      12,
      'Regular',
      '#72787F',
      1000
    )
  );

  const colors = POLARIS_SYNC_DATA.tokens.cssVariables.categorizedLight.colors;
  const grid = figma.createFrame();
  grid.name = 'Color variables';
  grid.layoutMode = 'HORIZONTAL';
  grid.layoutWrap = 'WRAP';
  grid.itemSpacing = 12;
  grid.counterAxisSpacing = 16;
  grid.primaryAxisSizingMode = 'FIXED';
  grid.counterAxisSizingMode = 'AUTO';
  grid.resize(1200, 10);
  grid.fills = [];
  for (const [name, value] of Object.entries(colors).slice(0, 120)) {
    const item = figma.createFrame();
    item.name = 'Token/' + name;
    auto(item, 'VERTICAL', 6, 0);
    item.fills = [];
    const swatch = figma.createRectangle();
    swatch.resize(120, 52);
    swatch.cornerRadius = 8;
    swatch.fills = paint(value);
    item.appendChild(swatch);
    item.appendChild(await makeText(name, 10, 'Regular', '#454C53', 120));
    grid.appendChild(item);
  }
  root.appendChild(grid);

  const typeFrame = figma.createFrame();
  typeFrame.name = 'Typography styles';
  typeFrame.resize(1200, 10);
  typeFrame.fills = [];
  auto(typeFrame, 'VERTICAL', 12, 0);
  typeFrame.appendChild(await makeText('Typography', 24, 'Bold', '#26282B', 1000));
  for (const [name, spec] of Object.entries(POLARIS_SYNC_DATA.tokenRegistry.typography.styles)) {
    const row = figma.createFrame();
    row.name = 'Type/' + name;
    row.resize(1100, 10);
    row.fills = [];
    auto(row, 'HORIZONTAL', 16, 0);
    row.appendChild(await makeText(name, 12, 'Regular', '#72787F', 120));
    const weight = Number(spec.fontWeight) >= 700 ? 'Bold' : 'Regular';
    row.appendChild(await makeText('The quick brown fox / 폴라리스 오피스', parsePx(spec.fontSize), weight, '#26282B', 620));
    row.appendChild(await makeText(spec.fontSize + ' / ' + spec.lineHeight + ' / ' + spec.fontWeight, 11, 'Regular', '#72787F', 220));
    typeFrame.appendChild(row);
  }
  root.appendChild(typeFrame);

  const gridFrame = figma.createFrame();
  gridFrame.name = 'Grid spacing breakpoints';
  gridFrame.resize(1200, 10);
  gridFrame.fills = [];
  auto(gridFrame, 'VERTICAL', 16, 0);
  gridFrame.appendChild(await makeText('Grid / Spacing / Breakpoints', 24, 'Bold', '#26282B', 1000));
  for (const [name, value] of Object.entries(POLARIS_SYNC_DATA.tokenRegistry.grid.spacingNamed)) {
    const row = figma.createFrame();
    row.name = 'Spacing/' + name;
    row.resize(760, 10);
    row.fills = [];
    auto(row, 'HORIZONTAL', 12, 0);
    row.appendChild(await makeText(name, 12, 'Regular', '#72787F', 96));
    const bar = figma.createRectangle();
    bar.resize(Math.max(2, parsePx(value)) * 4, 12);
    bar.cornerRadius = 2;
    bar.fills = paint('#1D7FF9');
    row.appendChild(bar);
    row.appendChild(await makeText(value, 12, 'Regular', '#454C53', 120));
    gridFrame.appendChild(row);
  }
  const breakpointText = Object.entries(POLARIS_SYNC_DATA.tokenRegistry.grid.breakpoint)
    .map(([name, value]) => name + ': ' + value)
    .join(' / ');
  gridFrame.appendChild(await makeText('Breakpoints: ' + breakpointText, 12, 'Regular', '#454C53', 1000));
  root.appendChild(gridFrame);
}

async function buildComponentPage() {
  const page = await ensurePage('Polaris DS - Components');
  const root = figma.createFrame();
  root.name = 'Polaris Component Contract';
  root.resize(1440, 1200);
  root.fills = paint('#F7F8F9');
  auto(root, 'VERTICAL', 24, 64);
  page.appendChild(root);
  root.appendChild(await makeText('Polaris Components', 32, 'Bold', '#26282B', 1000));
  root.appendChild(
    await makeText(
      'Component families: ' + POLARIS_SYNC_DATA.components.familyCount + '. Subpaths: ' + POLARIS_SYNC_DATA.components.subpaths.map((item) => item.path).join(', '),
      14,
      'Regular',
      '#454C53',
      1000
    )
  );
  root.appendChild(
    await makeText(
      'Pages demo sections: ' + POLARIS_SYNC_DATA.componentRegistry.summary.demoSectionCount + '. Root exports used by demo: ' + POLARIS_SYNC_DATA.componentRegistry.summary.demoImportCount + '.',
      14,
      'Regular',
      '#454C53',
      1000
    )
  );
  const categorySummary = Object.entries(POLARIS_SYNC_DATA.componentRegistry.demo.categories)
    .map(([category, sections]) => category + ' ' + sections.length)
    .join(' / ');
  root.appendChild(await makeText('Pages categories: ' + categorySummary, 12, 'Regular', '#72787F', 1000));
  root.appendChild(
    await makeText(
      POLARIS_SYNC_DATA.components.components.slice(0, 80).join(' / '),
      13,
      'Regular',
      '#454C53',
      1000
    )
  );
  root.appendChild(
    await makeText(
      'Secondary exports captured from source: ' + POLARIS_SYNC_DATA.componentRegistry.demo.secondaryExportsMissingFromFamilyCatalog.slice(0, 80).join(' / '),
      12,
      'Regular',
      '#454C53',
      1000
    )
  );
}

async function main() {
  setColorVariables();
  setNumberVariables();
  await setTextStyles();
  setEffectStyles();
  await buildContractPage();
  await buildTokenPage();
  await buildComponentPage();
  figma.root.setSharedPluginData('polaris.design', 'upstreamCommit', POLARIS_SYNC_DATA.tokens.source.commit);
  figma.root.setSharedPluginData('polaris.design', 'tokensJsonSha256', POLARIS_SYNC_DATA.manifest.tokensJsonSha256);
  figma.root.setSharedPluginData('polaris.design', 'syncedAt', POLARIS_SYNC_DATA.tokens.generatedAt);
  const colorCollection = figma.variables
    .getLocalVariableCollections()
    .find((collection) => collection.name === 'Polaris / Color');
  const numberCollection = figma.variables
    .getLocalVariableCollections()
    .find((collection) => collection.name === 'Polaris / Number');
  const localVariables = figma.variables.getLocalVariables();
  const pages = figma.root.children
    .filter((page) => page.name === '00 Polaris Output Contract' || page.name.startsWith('Polaris DS - '))
    .map((page) => ({ id: page.id, name: page.name }));
  return {
    status: 'synced',
    pages,
    colorVariables: colorCollection
      ? localVariables.filter((variable) => variable.variableCollectionId === colorCollection.id).length
      : 0,
    numberVariables: numberCollection
      ? localVariables.filter((variable) => variable.variableCollectionId === numberCollection.id).length
      : 0,
    textStyles: figma.getLocalTextStyles().filter((style) => style.name.startsWith('Polaris/')).length,
    effectStyles: figma.getLocalEffectStyles().filter((style) => style.name.startsWith('Polaris/shadow/')).length,
    sharedPluginData: {
      upstreamCommit: figma.root.getSharedPluginData('polaris.design', 'upstreamCommit'),
      tokensJsonSha256: figma.root.getSharedPluginData('polaris.design', 'tokensJsonSha256'),
      syncedAt: figma.root.getSharedPluginData('polaris.design', 'syncedAt'),
    },
  };
}

return await main();
